import * as T from './vendor/three.module.js';
const vec=(x,y,z)=>new T.Vector3(x,y,z);
export class BirthdayRoom{
 constructor(container){this.container=container;this.renderer=new T.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.setSize(innerWidth,innerHeight);this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.shadowMap.autoUpdate=false;this.renderer.shadowMap.needsUpdate=true;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.12;container.append(this.renderer.domElement);this.scene=new T.Scene();this.scene.background=new T.Color('#07101c');this.camera=new T.PerspectiveCamera(48,innerWidth/innerHeight,.1,120);this.camera.position.set(2.3,2.55,7.2);this.look=vec(0,2.65,-5.2);this.targetPos=this.camera.position.clone();this.targetLook=this.look.clone();this.mouse={x:0,y:0};this.time=0;this.mode='entry';this.lit=false;this.reduced=false;this.loader=new T.TextureLoader();this.ready=this.build();window.addEventListener('resize',()=>this.resize());}
 mat(color,roughness=.65,metalness=0){return new T.MeshStandardMaterial({color,roughness,metalness});}
 mesh(geo,mat,pos,parent=this.scene){const m=new T.Mesh(geo,mat);m.position.copy(pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
 box(w,h,d,mat,x,y,z,parent){return this.mesh(new T.BoxGeometry(w,h,d),mat,vec(x,y,z),parent);}
 cylinder(rt,rb,h,mat,x,y,z,parent){return this.mesh(new T.CylinderGeometry(rt,rb,h,64),mat,vec(x,y,z),parent);}
 async build(){const [skyTex,cakeTex]=await Promise.all([this.loader.loadAsync('./assets/aurora.png'),this.loader.loadAsync('./assets/cake-texture.png')]);skyTex.colorSpace=T.SRGBColorSpace;cakeTex.colorSpace=T.SRGBColorSpace;cakeTex.anisotropy=4;const s=this.scene;s.add(new T.HemisphereLight('#a9d9ea','#423341',1.25));const key=new T.SpotLight('#ffcf88',75,22,.7,.8,1.5);key.position.set(1.5,4.4,.3);key.target.position.set(.8,1,-.3);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.bias=-.0005;s.add(key,key.target);const cool=new T.PointLight('#75cbbd',25,18,1.5);cool.position.set(-3,3,-4);s.add(cool);this.sceneLight=cool;this.keyLight=key;this.skyTextures={aurora:skyTex};this.sceneName='aurora';this.sceneRequest=0;const fill=new T.PointLight('#bf99f9',10,12,1.5);fill.position.set(3,2,3);s.add(fill);
 const charcoal=this.mat('#253136',.45,.2),wood=this.mat('#60463b',.44),wall=this.mat('#657174'),gold=this.mat('#d7b887',.28,.72),cream=this.mat('#b8aa96');
 // The exterior is behind the window, so real foreground geometry gives camera motion depth.
 const sky=this.mesh(new T.PlaneGeometry(56,31.5),new T.MeshBasicMaterial({map:skyTex}),vec(0,4,-27));this.sky=sky;sky.castShadow=false;sky.receiveShadow=false;
 for(let i=0;i<49;i++){const m=this.mat(new T.Color('#544037').multiplyScalar(.8+(i%5)*.065),.46,.08);this.box(.318,.1,14,m,-8+i*.33,-.06,1);}
 // Panoramic 16 m glazing with only two slim vertical mullions, no mid-height rail.
 this.box(.2,6,13,wall,-8,3,1);this.box(.2,6,13,this.mat('#8c7560'),8,3,1);this.box(16,.2,13,this.mat('#302c2c'),0,6,1);
 this.box(16,.12,.22,charcoal,0,.08,-4.9);this.box(16,.12,.22,charcoal,0,5.9,-4.9);
 for(const x of [-8,-2.7,2.7,8])this.box(.045,5.8,.06,charcoal,x,3,-4.9);
 const glassMat=new T.MeshPhysicalMaterial({color:'#d7eeef',transparent:true,opacity:.018,roughness:.05,metalness:.1,side:T.DoubleSide,depthWrite:false});this.box(16,5.75,.02,glassMat,0,3,-4.94);
 for(const x of [-7.7,7.7])for(let i=0;i<6;i++){const curtain=this.box(.14,5.7,.2,this.mat('#b6a18a',.95),x+(x<0?i*.08:-i*.08),3,-4.6);curtain.scale.z=.8+Math.sin(i)*.3;}
 this.box(15.5,.025,.08,new T.MeshBasicMaterial({color:'#d6a668'}),0,5.83,-4.4);
 // Dining platform, upholstered lounge, sideboard and small architectural lights.
 this.cylinder(2.3,2.3,.025,this.mat('#303744',.98),.6,.01,.1);this.cylinder(1.36,1.36,.13,wood,.9,1.08,-.7);this.cylinder(.36,.62,1.04,charcoal,.9,.53,-.7);this.cylinder(1.38,1.38,.015,gold,.9,1.15,-.7);
 this.box(2.6,.36,1.04,this.mat('#59606b'),-3,.49,1.1);this.box(2.7,.9,.25,this.mat('#4c555d'),-3,.92,1.57);for(const x of [-4.35,-1.65])this.box(.2,.7,1.13,wood,x,.67,1.1);for(const x of [-4,-2])for(const z of [.8,1.5])this.box(.08,.35,.08,gold,x,.18,z);for(const x of [-3.6,-2.55]){const pillow=this.box(.67,.44,.24,this.mat(x<-3?'#8b7867':'#747f8c'),x,1.0,1.32);pillow.rotation.z=x<-3?.12:-.1;}
 // Compact flush-mounted memory wall; no chest, sideboard, or floor footprint.
 this.memoryWall=new T.Group();this.memoryWall.position.set(7.87,2.85,-3.25);this.memoryWall.rotation.y=-Math.PI/2;s.add(this.memoryWall);this.memoryFrames=[];
 for(let i=0;i<6;i++){const x=(i%2-.5)*.9,y=(1-Math.floor(i/2))*.72;this.box(.78,.6,.045,gold,x,y,0,this.memoryWall);const photo=this.mesh(new T.PlaneGeometry(.71,.53),new T.MeshBasicMaterial({map:skyTex}),vec(x,y,.029),this.memoryWall);this.memoryFrames.push(photo);}
 const waveMat=new T.MeshBasicMaterial({color:'#e7c387'});for(let i=0;i<40;i++){const h=.025+Math.abs(Math.sin(i*1.9)*Math.cos(i*.52))*.18;this.box(.012,h,.02,waveMat,(i-19.5)*.04,-1.12,.03,this.memoryWall);}
 const wallLight=new T.PointLight('#ffcf92',12,7,1.7);wallLight.position.set(6.6,3,-3.25);s.add(wallLight);this.wallPhotoTicket=0;
 for(const x of [-7.9,7.9]){this.box(.06,.7,.05,new T.MeshBasicMaterial({color:'#e8bb78'}),x,2.4,.4);const l=new T.PointLight('#ffd4a0',6,5);l.position.set(x*.94,2.4,.4);s.add(l);}

 // Tall blue-purple cake, textured frosting, two tilted orbital rings and an independent flame.
 this.cake=new T.Group();this.cake.position.set(.9,1.2,-.7);s.add(this.cake);const cm=new T.MeshPhysicalMaterial({map:cakeTex,roughness:.3,metalness:.12,clearcoat:.45,clearcoatRoughness:.25});this.cylinder(.68,.74,.055,this.mat('#b4bad9',.25,.5),0,.025,0,this.cake);this.cylinder(.51,.51,.83,cm,0,.465,0,this.cake);this.cylinder(.515,.515,.035,new T.MeshStandardMaterial({map:cakeTex,color:'#f1d9eb',roughness:.35}),0,.9,0,this.cake);this.cylinder(.035,.04,.36,this.mat('#d8a7e9',.4),0,1.1,0,this.cake);this.cylinder(.005,.005,.055,this.mat('#342322'),0,1.3,0,this.cake);
 this.rings=[];for(let j=0;j<2;j++){const ring=this.mesh(new T.TorusGeometry(j?.9:.83,.009,8,160),new T.MeshStandardMaterial({color:j?'#a5a0ff':'#ffe2a2',emissive:j?'#8a64d0':'#c6a76a',emissiveIntensity:.7,metalness:.4,roughness:.2}),vec(0,j?.98:.36,0),this.cake);ring.rotation.set(Math.PI/2-.27,j*.4,-.3);this.rings.push(ring);}const dustGeo=new T.BufferGeometry(),positions=[],colors=[];for(let i=0;i<150;i++){const angle=i*2.4,r=.62+(i%13)/16;positions.push(Math.cos(angle)*r,.2+(i%39)/26,Math.sin(angle)*r);const color=new T.Color(['#d6b273','#bccfff','#b682e6','#8ad4e0'][i%4]);colors.push(color.r,color.g,color.b);}dustGeo.setAttribute('position',new T.Float32BufferAttribute(positions,3));dustGeo.setAttribute('color',new T.Float32BufferAttribute(colors,3));this.cakeDust=new T.Points(dustGeo,new T.PointsMaterial({size:.025,vertexColors:true,transparent:true,opacity:.85,blending:T.AdditiveBlending,depthWrite:false}));this.cake.add(this.cakeDust);
 this.flame=this.mesh(new T.SphereGeometry(.07,20,24),new T.MeshBasicMaterial({color:'#ffdb80'}),vec(0,1.42,0),this.cake);this.flame.scale.set(.72,2.3,.72);this.flame.visible=false;this.flameGlow=this.mesh(new T.SphereGeometry(.11,16,16),new T.MeshBasicMaterial({color:'#ffac43',transparent:true,opacity:.13,depthWrite:false,blending:T.AdditiveBlending}),vec(0,1.42,0),this.cake);this.flameGlow.scale.set(1,1.8,1);this.flameGlow.visible=false;this.candleLight=new T.PointLight('#ffb752',0,4,1.5);this.candleLight.position.set(.9,2.63,-.7);s.add(this.candleLight);
 // Procedural aurora curtain overlays the exterior: animated, softly transparent ribbons.
 this.aurora=new T.Mesh(new T.PlaneGeometry(53,18),new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,uniforms:{time:{value:0},intensity:{value:1}},vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 vUv;uniform float time;uniform float intensity;void main(){float w=sin(vUv.x*8.+time*.15)*.12+sin(vUv.x*16.-time*.12)*.045;float band=exp(-pow((vUv.y-.65-w)*9.,2.));float lines=.55+.45*sin(vUv.x*180.+sin(vUv.x*18.+time*.2)*4.);vec3 c=mix(vec3(.08,.35,.46),vec3(.17,.75,.45),vUv.y);gl_FragColor=vec4(c,band*lines*.2*intensity);}' }));this.aurora.position.set(0,7,-22);s.add(this.aurora);
 this.anchors={memory:vec(7.55,2.8,-3.25),cake:vec(.9,2.8,-.7),window:vec(-3.8,3.3,-4.8)};this.camera.lookAt(this.look);return this;}
 setView(mode){this.mode=mode;this.skyTint=new T.Color(mode==='ending'?'#697589':'#ffffff');const mobile=innerWidth<650;const views={entry:[[mobile?1.1:2.3,2.55,mobile?8:7.2],[0,2.65,-5.2]],room:[[mobile?1.2:1.0,2.5,mobile?8.5:8.0],[mobile?0:1.0,2.65,-3.8]],memory:[[5.1,2.8,.0],[7.6,2.65,-3.25]],cake:[[mobile?2.4:3.4,2.65,mobile?3.7:3.4],[.55,1.8,-.7]],window:[[.15,2.45,-3.75],[0,3.8,-21]],ending:[[.15,2.45,-3.75],[0,4.2,-21]]};const [p,l]=views[mode]||views.room;this.targetPos.set(...p);this.targetLook.set(...l);}
 async setScene(name){
 const options={aurora:{path:'./assets/aurora.png',light:'#75cbbd',key:'#ffcf88'},sunset:{path:'./assets/sunset.png',light:'#ee9875',key:'#ffc28c'},garden:{path:'./assets/moon-garden.png',light:'#a391ec',key:'#f4d1a1'}};
 const preset=options[name];if(!preset)return false;const request=++this.sceneRequest;
 const texture=this.skyTextures[name]||await this.loader.loadAsync(preset.path);
 texture.colorSpace=T.SRGBColorSpace;this.skyTextures[name]=texture;if(request!==this.sceneRequest)return false;
 if(this.skyFade){this.scene.remove(this.skyFade);this.skyFade.material.dispose();}this.skyFade=new T.Mesh(this.sky.geometry,new T.MeshBasicMaterial({map:this.sky.material.map,transparent:true,depthWrite:false,opacity:1}));this.skyFade.position.copy(this.sky.position);this.skyFade.position.z+=.01;this.skyFadeAge=0;this.scene.add(this.skyFade);
 this.sky.material.map=texture;this.sky.material.needsUpdate=true;this.sceneLight.color.set(preset.light);this.keyLight.color.set(preset.key);this.aurora.visible=name==='aurora';this.sceneName=name;return true;
 }
 async setMemories(items){const ticket=++this.wallPhotoTicket;const photos=items.filter(m=>m.type==='photo');if(!photos.length)return;
 const textures=await Promise.all(photos.map(async p=>{try{const t=await this.loader.loadAsync(p.src);t.colorSpace=T.SRGBColorSpace;return t;}catch{return null;}}));
 if(ticket!==this.wallPhotoTicket){textures.forEach(t=>t?.dispose());return;}const previous=this.wallTextures||[];this.wallTextures=textures;this.memoryFrames.forEach((m,i)=>{m.material.map=textures[i%textures.length]||this.skyTextures.aurora;m.material.needsUpdate=true;});previous.forEach(t=>t?.dispose());}
 setLit(lit){this.lit=lit;this.flame.visible=lit;this.flameGlow.visible=lit;this.candleLight.intensity=lit?5:0;}
 resize(){this.camera.aspect=innerWidth/innerHeight;this.camera.fov=innerWidth<650?59:48;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);this.setView(this.mode);}
 project(name){const p=this.anchors[name].clone().project(this.camera);return{x:(p.x*.5+.5)*innerWidth,y:(-.5*p.y+.5)*innerHeight,visible:p.z<1&&Math.abs(p.x)<.95&&Math.abs(p.y)<.95};}
 update(dt,t){if(this.sky&&this.skyTint)this.sky.material.color.lerp(this.skyTint,1-Math.exp(-dt*.7));if(this.skyFade){this.skyFadeAge+=dt;this.skyFade.material.opacity=Math.max(0,1-this.skyFadeAge/(this.reduced?.15:1.4));if(this.skyFade.material.opacity===0){this.scene.remove(this.skyFade);this.skyFade.material.dispose();this.skyFade=null;}}this.camera.position.lerp(this.targetPos,1-Math.exp(-dt*(this.reduced?20:1.25)));this.look.lerp(this.targetLook,1-Math.exp(-dt*(this.reduced?20:1.35)));const drift=this.reduced?0:.07;const target=this.look.clone().add(vec(this.mouse.x*.16+Math.sin(t*.12)*drift,this.mouse.y*.055,0));this.camera.lookAt(target);if(this.aurora){this.aurora.material.uniforms.time.value=this.reduced?0:t;this.aurora.material.uniforms.intensity.value=this.mode==='ending'?.22:1;}if(this.memoryOrb){this.memoryOrb.position.y=1.42+(this.reduced?0:Math.sin(t*1.4)*.04);this.memoryOrb.rotation.y=t*.3;}if(this.cakeDust&&!this.reduced){this.cakeDust.rotation.y=t*.11;this.rings.forEach((r,i)=>r.rotation.z=-.3+Math.sin(t*.35+i)*.05);}if(this.lit){this.flame.scale.y=2.2+Math.sin(t*13)*.2;this.candleLight.intensity=5+Math.sin(t*17)*.3;}this.renderer.render(this.scene,this.camera);}
}
